mapper.select:


	is_del = 0

		AND menu_name like concat('%', #{menuName}, '%')


		AND hidden = #{visible}


		AND status = #{status}


order by parent_id, order_num

select distinct m.menu_id, m.parent_id, m.menu_name, m.menu_path, NULL as component, CASE WHEN m.keep_alive = 1 THEN '0' ELSE '1' END as is_cache, CAST(m.menu_type AS CHAR) as menu_type, m.hidden, m.status, ifnull(m.perms,'') as perms, m.icon, m.order_num, m.create_time from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id left join sys_user_role ur on rm.role_id = ur.role_id left join sys_role ro on ur.role_id = ro.role_id where ur.user_id = #{params.userId} and m.is_del = 0
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.hidden = #{visible}
AND m.status = #{status}
order by m.parent_id, m.order_num

mapper.update:
update sys_menu
menu_name = #{menuName}, parent_id = #{parentId}, order_num = #{orderNum}, menu_path = #{path}, keep_alive = CASE WHEN #{isCache} = '0' THEN 1 ELSE 0 END, menu_type = #{menuType}, hidden = #{visible}, status = #{status}, perms = #{perms}, icon = #{icon}, update_by = #{updateBy}, update_time = sysdate()
where menu_id = #{menuId}
